=== src/lib/error-capture.ts
     1	// Captures the original Error out-of-band so server.ts can recover the stack
     2	// when h3 has already swallowed the throw into a generic 500 Response.
     3	
     4	let lastCapturedError: { error: unknown; at: number } | undefined;
     5	const TTL_MS = 5_000;
     6	
     7	function record(error: unknown) {
     8	  lastCapturedError = { error, at: Date.now() };
     9	}
    10	
    11	// h3's HTTPError serializes to {"status":500,"unhandled":true,"message":"HTTPError"} —
    12	// no stack, no cause — so a plain console.error(error) reaches the log pipeline with
    13	// the failure detail stripped. Expand Error-like args into a string that keeps the
    14	// message, stack, and the full cause chain.
    15	const CAUSE_DEPTH_LIMIT = 5;
    16	const DESCRIPTION_LENGTH_LIMIT = 8_000;
    17	
    18	export function describeError(error: unknown): string {
    19	  const parts: string[] = [];
    20	  let current: unknown = error;
    21	  for (let depth = 0; depth < CAUSE_DEPTH_LIMIT && current != null; depth++) {
    22	    if (!(current instanceof Error)) {
    23	      parts.push(typeof current === "string" ? current : safeStringify(current));
    24	      break;
    25	    }
    26	    const label = depth === 0 ? "" : "caused by: ";
    27	    const status = describeStatus(current);
    28	    parts.push(`${label}${current.stack ?? `${current.name}: ${current.message}`}${status}`);
    29	    current = current.cause;
    30	  }
    31	  return parts.join("\n").slice(0, DESCRIPTION_LENGTH_LIMIT);
    32	}
    33	
    34	function describeStatus(error: Error): string {
    35	  const { status, statusCode } = error as { status?: unknown; statusCode?: unknown };
    36	  const value = status ?? statusCode;
    37	  return typeof value === "number" ? ` (status ${value})` : "";
    38	}
    39	
    40	function safeStringify(value: unknown): string {
    41	  try {
    42	    return JSON.stringify(value) ?? String(value);
    43	  } catch {
    44	    return String(value);
    45	  }
    46	}
    47	
    48	function isErrorLike(value: unknown): value is Error {
    49	  return value instanceof Error;
    50	}
    51	
    52	// Wrap console.error so errors logged by any layer — including h3's internal
    53	// unhandled-error logging, which this file cannot hook directly — are both
    54	// recorded for consumeLastCapturedError and expanded before serialization.
    55	const originalConsoleError = console.error.bind(console);
    56	console.error = (...args: unknown[]) => {
    57	  const expanded = args.map((arg) => {
    58	    if (!isErrorLike(arg)) return arg;
    59	    record(arg);
    60	    return describeError(arg);
    61	  });
    62	  originalConsoleError(...expanded);
    63	};
    64	
    65	if (typeof globalThis.addEventListener === "function") {
    66	  globalThis.addEventListener("error", (event) => record((event as ErrorEvent).error ?? event));
    67	  globalThis.addEventListener("unhandledrejection", (event) =>
    68	    record((event as PromiseRejectionEvent).reason),
    69	  );
    70	}
    71	
    72	export function consumeLastCapturedError(): unknown {
    73	  if (!lastCapturedError) return undefined;
    74	  if (Date.now() - lastCapturedError.at > TTL_MS) {
    75	    lastCapturedError = undefined;
    76	    return undefined;
    77	  }
    78	  const { error } = lastCapturedError;
    79	  lastCapturedError = undefined;
    80	  return error;
    81	}
