128	     1	// Captures the original Error out-of-band so server.ts can recover the stack
129	     2	// when h3 has already swallowed the throw into a generic 500 Response.
130	     3	
131	     4	let lastCapturedError: { error: unknown; at: number } | undefined;
132	     5	const TTL_MS = 5_000;
133	     6	
134	     7	function record(error: unknown) {
135	     8	  lastCapturedError = { error, at: Date.now() };
136	     9	}
137	    10	
138	    11	// h3's HTTPError serializes to {"status":500,"unhandled":true,"message":"HTTPError"} —
139	    12	// no stack, no cause — so a plain console.error(error) reaches the log pipeline with
140	    13	// the failure detail stripped. Expand Error-like args into a string that keeps the
141	    14	// message, stack, and the full cause chain.
142	    15	const CAUSE_DEPTH_LIMIT = 5;
143	    16	const DESCRIPTION_LENGTH_LIMIT = 8_000;
144	    17	
145	    18	export function describeError(error: unknown): string {
146	    19	  const parts: string[] = [];
147	    20	  let current: unknown = error;
148	    21	  for (let depth = 0; depth < CAUSE_DEPTH_LIMIT && current != null; depth++) {
149	    22	    if (!(current instanceof Error)) {
150	    23	      parts.push(typeof current === "string" ? current : safeStringify(current));
151	    24	      break;
152	    25	    }
153	    26	    const label = depth === 0 ? "" : "caused by: ";
154	    27	    const status = describeStatus(current);
155	    28	    parts.push(`${label}${current.stack ?? `${current.name}: ${current.message}`}${status}`);
156	    29	    current = current.cause;
157	    30	  }
158	    31	  return parts.join("\n").slice(0, DESCRIPTION_LENGTH_LIMIT);
