     1	// Which family member is using this device right now (per browser tab session).
     2	const KEY = "zv_mode";
     3	export type Mode = { kind: "parent" } | { kind: "child"; id: string; pin: string };
     4	
     5	export function getMode(): Mode | null {
     6	  if (typeof window === "undefined") return null;
     7	  try {
     8	    return JSON.parse(sessionStorage.getItem(KEY) || "null");
     9	  } catch {
    10	    return null;
    11	  }
    12	}
    13	export function setMode(m: Mode | null) {
    14	  if (m) sessionStorage.setItem(KEY, JSON.stringify(m));
    15	  else sessionStorage.removeItem(KEY);
    16	}
