     1	export type Frequency = "once" | "daily" | "weekly" | "monthly" | "yearly";
     2	
     3	const pad = (n: number) => String(n).padStart(2, "0");
     4	
     5	export function isoDate(d: Date): string {
     6	  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
     7	}
     8	
     9	function isoWeek(d: Date): { year: number; week: number } {
    10	  const t = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
    11	  const day = t.getUTCDay() || 7;
    12	  t.setUTCDate(t.getUTCDate() + 4 - day);
    13	  const yearStart = new Date(Date.UTC(t.getUTCFullYear(), 0, 1));
    14	  const week = Math.ceil(((t.getTime() - yearStart.getTime()) / 86400000 + 1) / 7);
    15	  return { year: t.getUTCFullYear(), week };
    16	}
