    18	/** Key of the current period: a new key means the chore resets for a new run. */
    19	export function periodKey(freq: Frequency, now: Date = new Date()): string {
    20	  switch (freq) {
    21	    case "once":
    22	      return "once";
    23	    case "daily":
    24	      return isoDate(now);
    25	    case "weekly": {
    26	      const { year, week } = isoWeek(now);
