     9	function serverSupabaseUrl(publicUrl: string, supabaseKey: string): string | undefined {
    10	  if (typeof window !== "undefined" || typeof process === "undefined") return undefined;
    11	  const serverUrl = process.env["SUPABASE_URL"]?.replace(/\/+$/, "");
    12	  if (
    13	    !serverUrl ||
    14	    serverUrl === publicUrl ||
    15	    process.env["SUPABASE_PUBLISHABLE_KEY"] !== supabaseKey
    16	  )
    17	    return undefined;
    18	  return serverUrl;
    19	}
