    21	function createSupabaseFetch(supabaseUrl: string, supabaseKey: string): typeof fetch {
    22	  const publicUrl = supabaseUrl.replace(/\/+$/, "");
    23	  const serverUrl = serverSupabaseUrl(publicUrl, supabaseKey);
    24	  return (input, init) => {
    25	    const headers = new Headers(
    26	      typeof Request !== "undefined" && input instanceof Request ? input.headers : undefined,
    27	    );
    28	
    29	    if (init?.headers) {
    30	      new Headers(init.headers).forEach((value, key) => headers.set(key, value));
    31	    }
    32	
    33	    // New Supabase API keys are opaque strings, not bearer JWTs.
    34	    if (
    35	      isNewSupabaseApiKey(supabaseKey) &&
    36	      headers.get("Authorization") === `Bearer ${supabaseKey}`
    37	    ) {
    38	      headers.delete("Authorization");
    39	    }
    40	
    41	    headers.set("apikey", supabaseKey);
    42	    if (serverUrl) {
    43	      const url = typeof input === "string" ? input : input instanceof URL ? input.href : input.url;
    44	      if (url.startsWith(`${publicUrl}/`)) {
    45	        const target = serverUrl + url.slice(publicUrl.length);
    46	        const request =
    47	          typeof input === "string" || input instanceof URL ? target : new Request(target, input);
    48	        return fetch(request, { ...init, headers });
    49	      }
    50	    }
    51	    return fetch(input, { ...init, headers });
    52	  };
    53	}
