    59	  const SUPABASE_PUBLISHABLE_KEY =
    60	    import.meta.env["VITE_SUPABASE_PUBLISHABLE_KEY"] || process.env["SUPABASE_PUBLISHABLE_KEY"];
    61	
    62	  if (!SUPABASE_URL || !SUPABASE_PUBLISHABLE_KEY) {
    63	    const missing = [
    64	      ...(!SUPABASE_URL ? ["SUPABASE_URL"] : []),
    65	      ...(!SUPABASE_PUBLISHABLE_KEY ? ["SUPABASE_PUBLISHABLE_KEY"] : []),
    66	    ];
    67	    const message = `Missing Supabase environment variable(s): ${missing.join(", ")}. Copy .env.example to .env and fill in your Supabase project values.`;
