    57	function ChildView() {
    58	  const t = useT();
    59	  const { childId } = Route.useParams();
    60	  const { tab = "tasks" } = Route.useSearch();
    61	  const navigate = useNavigate();
    62	  const { data: kids = [] } = useChildren();
