    67	  const me = kids.find((k) => k.id === childId);
    68	  useTitle("{name} | Zvezdica", { name: me?.name ?? "" });
    69	  const list = childChoreList(childId, chores, comps);
    70	  const totalEarned = pointsFor(childId, comps);
    71	  const { data: reds = [] } = useRedemptions();
    72	  const { data: allRewards = [] } = useRewards();
    73	  const points = availablePoints(childId, comps, reds);
    74	  const myRewards = rewardsFor(childId, allRewards);
    75	  const myReds = reds.filter((r) => r.child_id === childId);
    76	  const { goal, setGoal } = useGoal(childId);
    77	  const goalReward = myRewards.find((r) => r.id === goal);
    78	  const [redeeming, setRedeeming] = useState<Reward | null>(null);
    79	  const mine = comps.filter((c) => c.child_id === childId);
    80	  const approved = mine.filter((c) => c.status === "approved");
    81	  const { data: seenData, isSuccess: seenLoaded } = useSeenChores(childId);
    82	  const markSeen = useMarkChoresSeen(childId);
    83	  const [dismissed, setDismissed] = useState(false);
    84	  const recent = Date.now() - 2 * 86400000;
    85	  // no rows yet = first use: only chores from the last 2 days count as new
    86	  const seen = seenLoaded && seenData.size > 0 ? seenData : null;
    87	  const newOnes = !seenLoaded
    88	    ? []
    89	    : list.filter(
    90	        ({ chore, status }) =>
    91	          status === "todo" &&
    92	          (seen ? !seen.has(chore.id) : new Date(chore.created_at).getTime() > recent),
    93	      );
    94	  const newIds = new Set(newOnes.map((n) => n.chore.id));
    95	  useEffect(() => {
    96	    if (seenLoaded && seenData.size === 0 && chores.length) {
    97	      const old = list
    98	        .filter(({ chore }) => new Date(chore.created_at).getTime() <= recent)
    99	        .map(({ chore }) => chore.id);
   100	      void markSeen(old);
   101	    }
   102	    // eslint-disable-next-line react-hooks/exhaustive-deps
   103	  }, [seenLoaded, chores.length]);
   104	
   105	  async function done(choreId: string, key: string) {
   106	    const m = getMode();
   107	    if (m?.kind !== "child") return;
