    46	  useEffect(() => {
    47	    if (!open) return;
    48	    setF(
    49	      chore
    50	        ? {
    51	            title: chore.title,
    52	            description: chore.description ?? "",
    53	            points: String(chore.points),
    54	            frequency: chore.frequency,
    55	            start: chore.start_date,
    56	            end: chore.end_date ?? "",
    57	            kids: chore.chore_assignments.map((a) => a.child_id),
    58	          }
    59	        : { ...empty, kids: kids.length === 1 ? [kids[0]!.id] : [] },
