    64	  async function save(e: React.FormEvent) {
    65	    e.preventDefault();
    66	    const pts = Number(f.points);
    67	    if (!f.title.trim()) {
    68	      toast.error(t("Vnesi naziv opravila."));
    69	      return;
    70	    }
    71	    if (!Number.isInteger(pts) || pts < 1) {
    72	      toast.error(t("Točke morajo biti celo število, večje od 0."));
    73	      return;
    74	    }
    75	    if (f.end && f.end < f.start) {
