                aria-label={t("Izbriši")}
                onClick={() => remove(k)}
              >
                <Trash2 />
              </Button>
            </div>
          </div>
        ))}
      </div>

      <Dialog open={!!dlg} onOpenChange={(o) => !o && setDlg(null)}>
        <DialogContent className="max-h-[92vh] max-w-[calc(100vw-1.5rem)] overflow-y-auto rounded-3xl sm:max-w-md">
