import { createFileRoute, useNavigate } from "@tanstack/react-router";
import { useEffect, useState } from "react";
import { toast } from "sonner";
import { LogOut } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { supabase } from "@/integrations/supabase/client";
import { errMsg, useFamily, useInvalidateAll } from "@/lib/data";
import { setMode } from "@/lib/mode";
import { LANGS, setLang, useT, useTitle } from "@/lib/i18n";
import { cn } from "@/lib/utils";

export const Route = createFileRoute("/_authenticated/parent/settings")({
  head: () => ({
    meta: [
      { title: "Nastavitve | Zvezdica" },
      { name: "description", content: "Nastavitve družine." },
      { property: "og:title", content: "Nastavitve | Zvezdica" },
      { property: "og:description", content: "Nastavitve družine." },
    ],
  }),
  component: Settings,
});

function Settings() {
  const { data: family } = useFamily();
  const refresh = useInvalidateAll();
  const t = useT();
  useTitle("Nastavitve | Zvezdica");
  const navigate = useNavigate();
  const [f, setF] = useState({ name: "", parent: "" });
  useEffect(() => {
    if (family) setF({ name: family.name, parent: family.parent_name });
  }, [family]);

  async function save(e: React.FormEvent) {
    e.preventDefault();
    if (!family || !f.name.trim()) {
      toast.error(t("Ime družine je obvezno."));
      return;
    }
    const { error } = await supabase
      .from("families")
      .update({ name: f.name.trim(), parent_name: f.parent.trim() })
      .eq("id", family.id);
    if (error) {
      toast.error(errMsg(error));
      return;
    }
    toast.success(t("Shranjeno"));
    refresh();
  }

  return (
    <div className="max-w-xl space-y-6">
      <h1>{t("Nastavitve")}</h1>
      <form onSubmit={save} className="space-y-4 rounded-2xl bg-card p-4 shadow-soft xs:p-6">
        <div className="space-y-1.5">
          <Label>{t("Ime družine")}</Label>
          <Input value={f.name} onChange={(e) => setF({ ...f, name: e.target.value })} />
        </div>
        <div className="space-y-1.5">
          <Label>{t("Tvoje ime")}</Label>
          <Input value={f.parent} onChange={(e) => setF({ ...f, parent: e.target.value })} />
        </div>
        <Button type="submit" className="btn-block">
          {t("Shrani")}
        </Button>
      </form>
      <section className="space-y-3 rounded-2xl bg-card p-4 shadow-soft xs:p-6">
        <div>
          <h2>{t("Jezik")}</h2>
          <p className="text-sm text-muted-foreground">{t("Jezik aplikacije na tej napravi.")}</p>
        </div>
        <div className="grid grid-cols-1 gap-2 xs:grid-cols-3">
          {LANGS.map((l) => (
            <Button
              key={l.code}
              type="button"
              variant={t.lang === l.code ? "default" : "outline"}
              className={cn("min-h-11")}
              onClick={() => setLang(l.code)}
              aria-pressed={t.lang === l.code}
            >
              {l.label}
            </Button>
          ))}
        </div>
      </section>
      <Button
        variant="outline"
        className="btn-block"
        onClick={async () => {
          setMode(null);
          await supabase.auth.signOut();
          navigate({ to: "/" });
        }}
      >
        <LogOut /> {t("Odjava")}
      </Button>
    </div>
  );
}

import { createFileRoute, useNavigate } from "@tanstack/react-router";
import { useT, useTitle } from "@/lib/i18n";
import { useState } from "react";
import { toast } from "sonner";
import { LogOut, ShieldCheck } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { PinInput } from "@/components/PinInput";
import { supabase } from "@/integrations/supabase/client";
import { useChildren, useFamily, type Child } from "@/lib/data";
import { setMode } from "@/lib/mode";
import { isValidPin } from "@/lib/periods";

export const Route = createFileRoute("/_authenticated/profiles")({
  head: () => ({
    meta: [
      { title: "Kdo si? | Zvezdica" },
      { name: "description", content: "Izberi svoj profil v družini." },
      { property: "og:title", content: "Kdo si? | Zvezdica" },
      { property: "og:description", content: "Izberi svoj profil v družini." },
    ],
  }),
  component: Profiles,
});

function Profiles() {
  const t = useT();
  useTitle("Kdo si? | Zvezdica");
  const navigate = useNavigate();
  const { data: family } = useFamily();
  const { data: children = [] } = useChildren();
  const [child, setChild] = useState<Child | null>(null);
  const [pin, setPin] = useState("");
  const [parentOpen, setParentOpen] = useState(false);
  const [pw, setPw] = useState("");
  const [busy, setBusy] = useState(false);

  async function tryPin(value: string) {
    if (!child) return;
    if (!isValidPin(value)) {
      toast.error(t("PIN mora imeti točno 6 številk."));
      return;
    }
    setBusy(true);
    const { data, error } = await supabase.rpc("verify_child_pin", {
      _child_id: child.id,
      _pin: value,
    });
    setBusy(false);
    if (error || !data) {
      setPin("");
      {
        toast.error(t("Napačen PIN. Poskusi znova."));
        return;
      }
    }
    setMode({ kind: "child", id: child.id, pin: value });
    navigate({ to: "/child/$childId", params: { childId: child.id } });
  }

  async function parentLogin(e: React.FormEvent) {
    e.preventDefault();
    setBusy(true);
    const { data: u } = await supabase.auth.getUser();
    const { error } = await supabase.auth.signInWithPassword({
      email: u.user?.email ?? "",
      password: pw,
    });
    setBusy(false);
    if (error) {
      toast.error(t("Napačno geslo."));
      return;
    }
    setMode({ kind: "parent" });
    navigate({ to: "/parent" });
  }

  return (
    <main className="mx-auto flex min-h-screen max-w-3xl flex-col px-4 py-8 md:px-8">
      <div className="mb-8 text-center">
        <p className="text-sm font-bold text-muted-foreground">{family?.name}</p>
        <h1>{t("Kdo si? 👋")}</h1>
      </div>
      <div className="grid grid-cols-1 gap-3 xs:grid-cols-2 md:grid-cols-3">
        {children.map((c) => (
          <button
            key={c.id}
            onClick={() => {
              setChild(c);
              setPin("");
            }}
            className="flex min-h-24 flex-col items-center justify-center gap-2 rounded-3xl bg-card p-5 shadow-soft transition hover:-translate-y-0.5"
          >
            <span className="avatar-lg flex items-center justify-center rounded-full bg-secondary">
              {c.avatar}
            </span>
            <span className="font-display text-lg font-semibold">{c.name}</span>
          </button>
        ))}
        <button
          onClick={() => setParentOpen(true)}
          className="flex min-h-24 flex-col items-center justify-center gap-2 rounded-3xl border-2 border-dashed bg-muted p-5"
        >
          <ShieldCheck className="h-8 w-8 text-primary" />
          <span className="font-display text-lg font-semibold">{t("Starš")}</span>
        </button>
      </div>
      {children.length === 0 && (
        <p className="mt-6 text-center text-muted-foreground">
          {t("Ni še otrok. Prijavi se kot starš in jih dodaj.")}
        </p>
      )}
      <Button
        variant="ghost"
        className="mx-auto mt-10"
        onClick={() => {
          setMode(null);
          supabase.auth.signOut();
          navigate({ to: "/" });
        }}
      >
        <LogOut /> {t("Odjava naprave")}
      </Button>

      <Dialog open={!!child} onOpenChange={(o) => !o && setChild(null)}>
        <DialogContent className="max-w-[calc(100vw-2rem)] rounded-3xl sm:max-w-md">
          <DialogHeader>
            <DialogTitle className="text-center font-display text-2xl">
              {child?.avatar} {t("Živjo, {name}!", { name: child?.name })}
            </DialogTitle>
          </DialogHeader>
          <p className="text-center text-muted-foreground">{t("Vnesi svoj 6-mestni PIN")}</p>
          <PinInput value={pin} onChange={setPin} autoFocus onComplete={tryPin} />
          <Button
            variant="hero"
            size="lg"
            className="w-full"
            disabled={busy}
            onClick={() => tryPin(pin)}
          >
            {t("Prijava")}
          </Button>
        </DialogContent>
      </Dialog>

      <Dialog open={parentOpen} onOpenChange={setParentOpen}>
        <DialogContent className="max-w-[calc(100vw-2rem)] rounded-3xl sm:max-w-md">
          <DialogHeader>
            <DialogTitle className="font-display text-2xl">{t("Starševski dostop")}</DialogTitle>
          </DialogHeader>
          <form onSubmit={parentLogin} className="space-y-4">
            <Input
              type="password"
              placeholder={t("Geslo")}
              value={pw}
              onChange={(e) => setPw(e.target.value)}
              autoFocus
              required
            />
            <Button type="submit" variant="hero" size="lg" className="w-full" disabled={busy}>
              {t("Prijava")}
            </Button>
          </form>
        </DialogContent>
      </Dialog>
    </main>
  );
}

