/** The parent reset this child's PIN while they were logged in: ask for the new one. */
function handleRpcError(error: { message: string }) {
  if (error.message === "Napačen PIN") {
    setMode(null);
    toast.error(t("Napačen PIN. Poskusi znova."));
    navigate({ to: "/profiles" });
    return;
  }
  toast.error(errMsg(error));
}

async function changeGoal(rewardId: string | null) {
  const error = await setGoal(rewardId);
  if (error) toast.error(errMsg(error));
}

async function done(choreId: string, key: string) {
  const m = getMode();
  if (m?.kind !== "child") return;
  setBusy(choreId);
  const { error } = await supabase.rpc("child_submit", {
    _child_id: childId,
    _pin: m.pin,
    _chore_id: choreId,
    _period_key: key,
  });
  setBusy(null);
  if (error) {
    handleRpcError(error);
    return;
  }
  void markSeen([choreId]);
  toast.success(t("Poslano staršem v pregled! 🚀"));
  refresh();
}

async function redeem(r: Reward) {
  const m = getMode();
  if (m?.kind !== "child") return;
  setBusy(r.id);
  const { error } = await supabase.rpc("child_redeem", {
    _child_id: childId,
    _pin: m.pin,
    _reward_id: r.id,
  });
  setBusy(null);
  setRedeeming(null);
  if (error) {
    handleRpcError(error);
    return;
  }
  if (goal === r.id) void changeGoal(null);
  toast.success(t("Zahtevek poslan staršem! 🎁"));
  refresh();
}

